const form=document.querySelector('#tryout-form'),key='qijian-human-trial-v1',status=document.querySelector('#trial-status');
let began=null;
try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved){began=saved.began||null;for(const [name,value] of Object.entries(saved.fields||{})){const input=form.elements.namedItem(name);if(input&&input.type!=='checkbox')input.value=value;}}}catch{}
const fields=()=>Object.fromEntries([...new FormData(form)].filter(([k])=>k!=='attested'));
form.addEventListener('input',()=>{try{localStorage.setItem(key,JSON.stringify({began,fields:fields()}));}catch{status.textContent='浏览器未允许保存草稿，仍可填写并导出。';}});
document.querySelector('#start-trial').addEventListener('click',()=>{const city=form.elements.city,hotel=form.elements.hotel;if(!city.reportValidity()||!hotel.reportValidity())return;began=new Date().toISOString();status.textContent='已开始计时。请完成三个任务后回到此页记录。';try{localStorage.setItem(key,JSON.stringify({began,fields:fields()}));}catch{}const url=new URL('/',location.origin);url.searchParams.set('city',city.value.trim());url.searchParams.set('findHotel',hotel.value.trim());window.open(url.href,'_blank','noopener');});
form.addEventListener('submit',event=>{event.preventDefault();if(!form.reportValidity())return;const ended=new Date().toISOString(),data={schemaVersion:1,kind:'human-self-reported-trial',startedAt:began,finishedAt:ended,elapsedSeconds:began?Math.round((Date.parse(ended)-Date.parse(began))/1000):null,attested:form.elements.attested.checked,...fields(),notice:'由体验者自行报告；未经独立现场核验；没有自动任务成功判定或响应时间测量。'};const link=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));link.href=url;link.download='qijian-trial-'+ended.slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent='反馈文件已准备下载，请确认浏览器已保存。谢谢你的真实反馈。';});
